arduino.globals:
#include <SPI.h>
#include "Adafruit_GFX.h"
#include "Adafruit_ILI9341.h"

#define TFT_DC_${COMP_SUFFIX}  ${DC}
#define TFT_CS_${COMP_SUFFIX}  ${CS}
#define TFT_RST_${COMP_SUFFIX} ${RESET}
#if defined(ARDUINO_ARCH_RP2040)
  #define TFT_MISO_${COMP_SUFFIX} ${MISO}
  #define TFT_MOSI_${COMP_SUFFIX} ${MOSI}
  #define TFT_SCK_${COMP_SUFFIX}  ${SCK}
#endif

Adafruit_ILI9341 tft_${COMP_SUFFIX}(TFT_CS_${COMP_SUFFIX}, TFT_DC_${COMP_SUFFIX}, TFT_RST_${COMP_SUFFIX});

arduino.setup:
#if defined(ARDUINO_ARCH_RP2040)
  SPI.setRX(TFT_MISO_${COMP_SUFFIX});
  SPI.setTX(TFT_MOSI_${COMP_SUFFIX});
  SPI.setSCK(TFT_SCK_${COMP_SUFFIX});
  SPI.begin();
#endif
  tft_${COMP_SUFFIX}.begin();
  tft_${COMP_SUFFIX}.setRotation(1);
  tft_${COMP_SUFFIX}.fillScreen(ILI9341_BLACK);
  tft_${COMP_SUFFIX}.setCursor(30, 60);
  tft_${COMP_SUFFIX}.setTextColor(ILI9341_WHITE);
  tft_${COMP_SUFFIX}.setTextSize(1);
  tft_${COMP_SUFFIX}.println("OpenHW Studio");
  tft_${COMP_SUFFIX}.setCursor(35, 90);
  tft_${COMP_SUFFIX}.setTextSize(1);
  tft_${COMP_SUFFIX}.println("ILI9341 Ready");
  delay(2000);

arduino.loop:
tft_${COMP_SUFFIX}.fillRect(30, 130, 180, 20, ILI9341_BLACK);
  tft_${COMP_SUFFIX}.setCursor(35, 140);
  tft_${COMP_SUFFIX}.setTextSize(1);
  tft_${COMP_SUFFIX}.setTextColor(ILI9341_WHITE);
  tft_${COMP_SUFFIX}.print("Time: ");
  tft_${COMP_SUFFIX}.print(millis()/1000);
  tft_${COMP_SUFFIX}.println("s");
  delay(500);
